-- So for match 335987: team_1=2, team_2=1, match_winner=1. So team 2 (Royal Challengers Bangalore) lost.
-- Now let's see which innings team 2 was batting in.
SELECT innings_no, team_batting FROM ball_by_ball WHERE match_id = 335987 AND innings_no = 1 LIMIT 5;

-- BB McCullum scored 158 in match 335987. Now let's verify: was he on the losing team (team 2)?
-- Let's check player_match for this match
SELECT player_id, team_id FROM player_match WHERE match_id = 335987 AND player_id = 2;
